public interface IInvoiceEngine
{
    Invoice Create(Order order);
}

public sealed class RoutingInvoiceEngine : IInvoiceEngine
{
    private readonly IInvoiceEngine _legacyEngine;
    private readonly IInvoiceEngine _newEngine;
    private readonly IFeatureFlags _flags;

    public RoutingInvoiceEngine(
        IInvoiceEngine legacyEngine,
        IInvoiceEngine newEngine,
        IFeatureFlags flags)
    {
        _legacyEngine = legacyEngine;
        _newEngine = newEngine;
        _flags = flags;
    }

    public Invoice Create(Order order)
    {
        bool useNewEngine = _flags.IsEnabled(
            "new-invoice",
            order.CustomerId);

        if (useNewEngine)
        {
            return _newEngine.Create(order);
        }

        return _legacyEngine.Create(order);
    }
}

